mapper.select:
select ,
       coalesce(l.title, d.title) as title

where c.goodscode = #{goodsCode}
  and c.combocode = #{comboCode}
  and c.status = '可选'

mapper.insert:
insert into u_s_sitegoods_combo_lang(
  shop_code, sitecode, goodscode, combocode, lang, title, createtime
) values(
  #{shopCode}, #{siteCode}, #{goodsCode}, #{comboCode}, #{lang}, #{title}, sysdate()
)
on duplicate key update title = values(title)

mapper.delete:
delete from u_s_sitegoods_combo
 where goodscode = #{goodsCode}

  and combocode not in
  #{code}

delete from u_s_sitegoods_combo_lang
 where goodscode = #{goodsCode}

  and combocode not in
  #{code}
